import json, os, datetime, textwrap, re
path="/mnt/data/SAT Theorizer Emeritus — raw.json"
with open(path,'r',encoding='utf-8') as f:
    data=json.load(f)
msgs=[]
for node_id,node in data.get("mapping",{}).items():
    m=node.get("message")
    if not m: continue
    ct=m.get("create_time")
    role=(m.get("author") or {}).get("role")
    content=m.get("content") or {}
    parts=content.get("parts")
    txt=""
    if isinstance(parts,list):
        vals=[]
        for p in parts:
            if isinstance(p,str): vals.append(p)
            elif isinstance(p,dict): vals.append(str(p))
        txt="\n".join(vals)
    if role in ("user","assistant") and txt.strip():
        msgs.append((ct or 0, role, txt.strip(), node_id))
msgs_sorted=sorted(msgs,key=lambda x:x[0])
len(msgs_sorted), msgs_sorted[-15:]

