def get_parts(m):
    c=m.get('content',{})
    parts=c.get('parts',[])
    out=[]
    for p in parts:
        if isinstance(p,str):
            out.append(p)
        elif isinstance(p,dict):
            # maybe structured
            if 'text' in p: out.append(p['text'])
    if not out and 'text' in c and isinstance(c['text'],str):
        out=[c['text']]
    return "\n".join(out)

visible=[]
for i,node in enumerate(path_nodes):
    m=node.get('message')
    if not m: continue
    role=m.get('author',{}).get('role')
    recipient=m.get('recipient')
    ctype=m.get('content',{}).get('content_type')
    if role=='user':
        txt=get_parts(m)
        visible.append((i,'USER',txt))
    elif role=='assistant':
        # include final text and maybe commentary text
        if recipient=='final' or (recipient=='commentary' and ctype=='text'):
            txt=get_parts(m)
            if txt.strip():
                visible.append((i, 'ASSISTANT FINAL' if recipient=='final' else 'ASSISTANT COMMENTARY', txt))
len(visible)

